package dev.cazajefes;
import org.junit.Test;
import static org.junit.Assert.*;
public class CombatExpansionTest {
 @Test public void armadilloCoversFiveSecondsAndWaitsFifteenBetweenStarts(){var c=new ArmadilloCycle();assertEquals(0,c.tick(0,true));assertEquals(0,c.tick(14999,true));assertEquals(1,c.tick(15000,true));assertTrue(c.active());assertEquals(0,c.tick(19999,false));assertEquals(2,c.tick(20000,false));assertFalse(c.active());assertEquals(0,c.tick(29999,true));assertEquals(1,c.tick(30000,true));assertEquals(1.8,ArmadilloCycle.healing(360),.000001);assertEquals(8,ArmadilloCycle.healing(10000),0);}
 @Test public void shulkerRecoveryHasItsOwnWindowWithoutChangingArmadillo(){var c=new ArmadilloCycle(25000,3000);assertEquals(0,c.tick(0,true));assertEquals(1,c.tick(25000,true));assertEquals(0,c.tick(27999,false));assertEquals(2,c.tick(28000,false));assertEquals(0,c.tick(49999,true));assertEquals(1,c.tick(50000,true));}
 @Test public void hordeReservationsRequireSixSlotsAndRespectBothLimits(){assertTrue(HordeRules.room(0,0));assertTrue(HordeRules.room(6,186));assertFalse(HordeRules.room(7,0));assertFalse(HordeRules.room(0,187));assertFalse(HordeRules.room(-1,0));assertEquals(6,HordeRules.SIZE);}
 @Test public void finalStageExtraDamageNeverStacksOnReborn(){assertEquals(1,PhaseRules.finalBonus(1,false),0);assertEquals(1,PhaseRules.finalBonus(2,false),0);assertEquals(1.05,PhaseRules.finalBonus(3,false),0);assertEquals(1,PhaseRules.finalBonus(3,true),0);}
 @Test public void whiteStarBurstScalesToTallAndWideBodies(){var points=BurstVisuals.scaledSphere(7,12);assertEquals(64,points.size());double maxY=0,maxR=0;for(var p:points){assertTrue(Math.abs(p.y())<=12);assertTrue(Math.hypot(p.x(),p.z())<=7.000001);maxY=Math.max(maxY,Math.abs(p.y()));maxR=Math.max(maxR,Math.hypot(p.x(),p.z()));}assertTrue(maxY>11);assertTrue(maxR>6);}
 @Test public void mageHealingAndRaysStayWithinTheirContracts(){assertEquals(6,MageRules.RAYS);assertEquals(30,MageRules.healing(1000),0);assertEquals(0,MageRules.healing(Double.NaN),0);assertEquals(15000,MageRules.HEAL_COOLDOWN);assertEquals(6,MageRules.rayDamage(2,false),0);assertEquals(6.3,MageRules.rayDamage(3,false),.000001);assertEquals(6,MageRules.rayDamage(3,true),0);}
 @Test public void bossLootOnlyPlansPlainEssencesInsteadOfPrebuiltPowerRewards(){for(var kind:LootRules.Kind.values()){assertNotEquals("RARE",kind.name());assertNotEquals("BOOK",kind.name());}boolean essence=false;for(int i=0;i<100;i++)for(var boss:BossCatalog.all())for(var reward:LootRules.roll(boss,new java.util.Random(i)))if(reward.kind()==LootRules.Kind.BASE_ESSENCE)essence=true;assertTrue(essence);}
 @Test public void stageNoticesUseTwoColorsWithoutStars(){var message=StageMessages.format(BossCatalog.all().iterator().next(),3);String plain=net.kyori.adventure.text.serializer.plain.PlainTextComponentSerializer.plainText().serialize(message);assertFalse(plain.contains("✦"));assertFalse(plain.contains("★"));java.util.Set<net.kyori.adventure.text.format.TextColor> colors=new java.util.HashSet<>();for(var child:message.children())if(child.color()!=null)colors.add(child.color());assertEquals(java.util.Set.of(net.kyori.adventure.text.format.NamedTextColor.GOLD,net.kyori.adventure.text.format.NamedTextColor.AQUA),colors);}
 @Test public void archersAndShortDebuffsHaveExactDefinitions(){assertTrue(SkeletonCombat.archer(org.bukkit.entity.EntityType.SKELETON));assertTrue(SkeletonCombat.archer(org.bukkit.entity.EntityType.STRAY));assertTrue(SkeletonCombat.archer(org.bukkit.entity.EntityType.BOGGED));assertFalse(SkeletonCombat.archer(org.bukkit.entity.EntityType.WITHER_SKELETON));assertEquals(200,BossEffects.duration("blindness",600));assertEquals(200,BossEffects.duration("nausea",600));assertEquals(600,BossEffects.duration("poison",40));}
}
